    n = len(sample)
    maximum = max(sample)
    log_n = math.log(n)
    centered_maximum = maximum - log_n

    # Compute exact finite-n CDF
    # P(Y_n <= y) = 0 if y < -log(n), else (1 - exp(-y)/n)^n
    if centered_maximum < -log_n:
