        exp_neg_y = math.exp(-centered_maximum)
        exact_cdf = (1.0 - exp_neg_y / n) ** n

    # Compute Gumbel CDF
    # G(y) = exp(-exp(-y))
    exp_neg_y = math.exp(-centered_maximum)
    gumbel_cdf = math.exp(-exp_neg_y)

    # Construct response
    response = {
        "sample_size": n,
        "maximum": maximum,
        "centered_maximum": centered_maximum,
        "exact_cdf_at_centered": exact_cdf,
        "gumbel_cdf_at_centered": gumbel_cdf
    }

